INSERT INTO instrumentos_inversion (nombre, categoria, riesgo, rentabilidad_min, rentabilidad_max, plazo_minimo_meses, monto_minimo, liquidez, donde_invertir, descripcion, consideraciones, fuente, fecha_referencia) VALUES
  ('Depósito a plazo en pesos', 'RENTA_FIJA_BANCARIA', 'BAJO', 3.8, 5.3, 1, 10000, 'Al vencimiento del plazo elegido (por ejemplo, 30 o 90 días)', 'Bancos supervisados por la CMF, muchos permiten contratarlo en línea', 'Entregas tu dinero a un banco por un plazo fijo y recibes un interés que conoces desde el inicio. A 30 días, los bancos pagan entre 0,31% y 0,43% mensual según la institución, lo que equivale a entre 3,8% y 5,3% anual.', 'Su rentabilidad en pesos puede quedar bajo la inflación (4,1% a 12 meses a septiembre de 2026). Si retiras antes del vencimiento puedes perder parte de los intereses. Compara tasas entre bancos porque la diferencia entre el mejor y el peor puede ser grande.', 'Tasas por banco: tasas.cl (noviembre 2026). Tasa de política monetaria de 4,5%: Banco Central de Chile (27 de octubre de 2026). Inflación: IPC a septiembre de 2026.', '2026-11-08'),
  ('Depósito a plazo en UF', 'RENTA_FIJA_BANCARIA', 'BAJO', 4.3, 5.7, 3, 100000, 'Al vencimiento (plazos desde 90 días)', 'Bancos supervisados por la CMF', 'Funciona como el depósito en pesos, pero el capital se reajusta con la UF, es decir, sigue a la inflación, y además paga una tasa real. Las tasas reales rondan entre 0,07% y 0,13% mensual según el banco.', 'Protege el poder de compra del dinero. Su rentabilidad en pesos depende de la inflación del período, por eso el rango es una aproximación (inflación de entre 3,4% y 4,1% más la tasa real). El monto mínimo depende del banco.', 'tasas.cl (noviembre 2026) e IPC de Chile. Cálculo propio: (1 + tasa real) x (1 + inflación) - 1.', '2026-11-08'),
  ('Fondo mutuo de renta fija de corto plazo (money market)', 'FONDOS_MUTUOS', 'BAJO', 3.5, 4.8, 1, 10000, '1 a 3 días hábiles al rescatar', 'Administradoras generales de fondos, bancos y plataformas digitales supervisadas por la CMF', 'Invierte en depósitos y bonos de muy corto plazo. Su rendimiento suele moverse cerca de la tasa de política monetaria (4,5%), menos las comisiones.', 'No tiene garantía estatal ni rentabilidad asegurada, aunque su variación es baja. Revisa la comisión y la serie del fondo, y cómo tributan las ganancias. El monto mínimo depende de la administradora.', 'Rango estimado a partir de la TPM de 4,5% (Banco Central de Chile, 27 de octubre de 2026). Confirma la rentabilidad real en la ficha de cada fondo.', '2026-11-08'),
  ('Fondo mutuo de renta fija de mediano y largo plazo', 'FONDOS_MUTUOS', 'MEDIO', -1.0, 7.0, 12, 10000, '2 a 4 días hábiles al rescatar', 'Administradoras generales de fondos, bancos y plataformas digitales supervisadas por la CMF', 'Invierte en bonos de mayor plazo. Su valor sube o baja cuando cambian las tasas de interés.', 'Puede tener meses con rentabilidad negativa. Conviene mantenerlo al menos un año.', 'Rango referencial de mercado, no corresponde a un fondo específico. Confirma en la ficha de cada fondo.', '2026-11-08'),
  ('Fondo mutuo balanceado (bonos y acciones)', 'FONDOS_MUTUOS', 'MEDIO', -8.0, 12.0, 36, 10000, '2 a 4 días hábiles al rescatar', 'Administradoras generales de fondos, bancos y plataformas digitales supervisadas por la CMF', 'Combina bonos y acciones para equilibrar riesgo y rentabilidad.', 'Un mal año puede dar pérdidas. Está pensado para plazos de tres años o más.', 'Rango referencial de mercado, no corresponde a un fondo específico. Confirma en la ficha de cada fondo.', '2026-11-08'),
  ('APV (Ahorro Previsional Voluntario)', 'PREVISIONAL', 'MEDIO', -8.0, 12.0, 120, 10000, 'Se puede retirar, pero un retiro anticipado puede hacerte perder beneficios tributarios', 'AFP, bancos, administradoras de fondos y aseguradoras autorizadas', 'Ahorro voluntario para tu pensión con beneficios tributarios. Régimen A: el Estado bonifica el 15% de lo que ahorras al año, con tope de 6 UTM. Régimen B: rebajas tu base imponible, con tope de 600 UF al año.', 'La rentabilidad depende del fondo que elijas, hay fondos de menor y de mayor riesgo. El régimen que más conviene depende de tus impuestos. Está pensado para el largo plazo. El rango de rentabilidad no incluye el beneficio tributario.', 'El Mostrador y Rankia Chile (octubre 2026). Confirma con la Superintendencia de Pensiones o el SII.', '2026-11-08'),
  ('Fondo mutuo o ETF de acciones chilenas (IPSA)', 'RENTA_VARIABLE', 'ALTO', -20.0, 25.0, 60, 10000, '2 a 4 días hábiles al rescatar o vender', 'Administradoras generales de fondos, plataformas y corredoras de bolsa autorizadas por la CMF', 'Invierte en las acciones de las principales empresas de la Bolsa de Santiago.', 'Es muy variable: el IPSA subió 56,2% en 2025, pero en 2026 cayó 5,7% en un solo mes (hasta el 22 de octubre) y acumulaba un alza de 4,8% en el año. Lo que ocurrió en el pasado no se repite necesariamente.', 'Bolsa de Santiago según CNN Chile (22 de octubre de 2026) y Ex-Ante (cierre de 2025). Son escenarios anuales de referencia, no proyecciones.', '2026-11-08'),
  ('Acciones individuales o ETF internacional', 'RENTA_VARIABLE', 'ALTO', -25.0, 30.0, 60, 50000, '2 días hábiles al vender', 'Corredoras de bolsa autorizadas por la CMF', 'Compras partes de empresas, locales o del exterior, o un ETF que replica un índice, por ejemplo el S&P 500.', 'Puede caer con fuerza. Si inviertes en el exterior, el valor del dólar también afecta tu resultado en pesos. Concentrar el dinero en pocas empresas aumenta el riesgo.', 'Escenarios anuales de referencia, no corresponden a un instrumento específico.', '2026-11-08'),
  ('Criptomonedas (por ejemplo, Bitcoin)', 'ALTERNATIVO', 'ALTO', -60.0, 100.0, 60, 10000, 'Alta, pero con precios muy variables', 'Plataformas de intercambio de activos digitales', 'Activos digitales cuyo precio sube y baja según la demanda. No pagan intereses ni dividendos.', 'Volatilidad extrema: puedes perder gran parte del dinero en poco tiempo. No cuentan con garantía del Estado. Solo con dinero que estés dispuesto a perder.', 'Escenarios amplios de referencia sobre la volatilidad de estos activos, no son proyecciones.', '2026-11-08');
